{"cards": [{"node_code": "N_b98b6b8a8519d80c", "definition": "研究岩体结构面内充填物（如粘土、岩屑、方解石等）的类型、厚度、物理力学性质及其对结构面抗剪强度、渗透性及变形特征的影响。", "boundary": "本节点聚焦于结构面内部填充介质的属性及其力学效应。边界包括充填物矿物成分、颗粒级配、含水状态、厚度变化及软硬充填物对摩擦系数和粘聚力的影响。不包含结构面壁面本身的粗糙度特征（归入粗糙度），也不包含结构面之间的空间连通关系（归入连通性）。", "includes": ["结构面充填物的矿物学、物理性质及厚度分布特征", "充填物对结构面抗剪强度、渗透系数及法向/切向刚度的影响机制", "不同含水状态及应力条件下充填物的流变与破坏行为"], "excludes": ["结构面壁面的几何粗糙度、起伏度及剪切位移特征（归入粗糙度）", "结构面在岩体中的空间分布、间距及连通网络特征（归入连通性）"], "sibling_distinctions": [{"other_code": "N_764554ac382651c5", "rule": "本节点关注结构面内部填充物的性质及其对力学参数的影响；兄弟节点关注结构面壁面本身的几何粗糙度及剪切位移特征。"}, {"other_code": "N_ee3b1f49eec4122e", "rule": "本节点关注单个结构面内部的介质属性；兄弟节点关注结构面在三维空间中的连通性、渗透路径及网络特征。"}], "cross_boundary_rule": "涉及结构面抗剪强度测试中充填物与壁面粗糙度的耦合效应，若侧重充填物性质主挂载于本节点，若侧重壁面几何特征主挂载于粗糙度。"}, {"node_code": "N_9fbaf259997c4bcd", "definition": "研究岩体中结构面（节理、裂隙、断层等）的空间方位、倾角、倾向及间距等几何特征的描述、统计与分类方法。", "boundary": "本节点聚焦于结构面的几何方位与分布规律。边界包括产状测量方法、极射赤平投影分析、结构面组划分、间距统计及优势产状识别。不包含结构面壁面的粗糙度特征（归入粗糙度），也不包含结构面内的充填物性质（归入充填）。", "includes": ["结构面产状（倾向、倾角）的测量、记录与统计方法", "极射赤平投影、玫瑰图等结构面空间分布分析技术", "结构面组划分、优势产状识别及间距、频率统计"], "excludes": ["结构面壁面的几何粗糙度、起伏度及剪切位移特征（归入粗糙度）", "结构面内部充填物的类型、厚度及力学性质（归入充填）"], "sibling_distinctions": [{"other_code": "N_764554ac382651c5", "rule": "本节点关注结构面的空间方位与分布（宏观几何）；兄弟节点关注结构面壁面的微观几何特征（粗糙度）。"}, {"other_code": "N_b98b6b8a8519d80c", "rule": "本节点关注结构面的空间位置与方位；兄弟节点关注结构面内部填充介质的属性。"}], "cross_boundary_rule": "涉及结构面产状对岩体各向异性或稳定性的影响，若侧重产状统计与描述主挂载于本节点，若侧重基于产状的稳定性计算主挂载于岩体稳定分析。"}]}
